#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Create a string stream to hold the markdown text
    std::stringstream ss(markdown);

    // Convert the markdown text to HTML
    std::string html;
    ss >> html;

    return html;
